{
  "findings": [
    {
      "check_id": "CKV_AZURE_3",
      "title": "Ensure that 'enable_https_traffic_only' is enabled",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "HIGH",
      "explanation": "The storage account allows HTTP traffic, which risks data interception and man-in-the-middle attacks. HTTPS-only should be enforced."
    },
    {
      "check_id": "CKV_AZURE_44",
      "title": "Ensure Storage Account is using the latest version of TLS encryption",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "The minimum TLS version is set to TLS1_0, which is deprecated and insecure. It should be updated to at least TLS1_2."
    },
    {
      "check_id": "CKV_AZURE_59",
      "title": "Ensure that Storage accounts disallow public access",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "Public network access is not explicitly restricted. The default behavior may allow public access depending on subscription policies; it should be explicitly disabled or restricted via private endpoints."
    },
    {
      "check_id": "CKV2_AZURE_47",
      "title": "Ensure storage account is configured without blob anonymous access",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "Anonymous blob access is not explicitly disabled in the configuration. This could lead to unintended data exposure if container-level permissions are misconfigured elsewhere."
    },
    {
      "check_id": "CKV2_AZURE_40",
      "title": "Ensure storage account is not configured with Shared Key authorization",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "Shared key authorization is enabled by default. Disabling it enforces the use of Azure AD RBAC for authentication, which is more secure and auditable."
    },
    {
      "check_id": "CKV2_AZURE_41",
      "title": "Ensure storage account is configured with SAS expiration policy",
      "resource": "azurerm_storage_account.media_storage",
      "severity": "MEDIUM",
      "explanation": "No SAS token expiration policy is defined. Without this, generated SAS tokens could remain valid indefinitely, increasing the risk of credential leakage."
    }
  ],
  "patched_code": "resource \"azurerm_storage_account\" \"media_storage\" {\n  name                     = \"corpmediastorage${random_string.storage_suffix.result}\"\n  resource_group_name      = azurerm_resource_group.corporate_media_streaming.name\n  location                 = azurerm_resource_group.corporate_media_streaming.location\n  account_tier             = \"Standard\"\n  account_replication_type = \"GRS\"\n  enable_https_traffic_only = true\n  min_tls_version          = \"TLS1_2\"\n  public_network_access_enabled = false\n  shared_key_authorization     = false\n  sas_policy {\n    expiration_action = \"LogOff\"\n    expiration_period = \"P0D\"\n  }\n  blob_properties {\n    versioning_enabled = true\n    delete_retention_policy {\n      days = 7\n    }\n    container_delete_retention_policy {\n      days = 7\n    }\n  }\n}",
  "fix_summary": "Enabled HTTPS-only traffic, upgraded minimum TLS version to 1.2, disabled public network access, disabled shared key authorization, added a SAS expiration policy, and enabled soft-delete retention policies for blobs and containers."
}
